/// The longest punctuation token at the start of `s` and its length.
#[inline]
pub fn punctuation(s: &[u8]) -> Option<(TokenKind, usize)> {
    let first = *s.first()?;
    match first {
        b'!' => {
            if s.starts_with(b"!=") {
                return Some((TokenKind::NotEqualExeq, 2));
            }
            Some((TokenKind::ExclamationMark, 1))
        }
        b'(' => {
            Some((TokenKind::Lparen, 1))
        }
        b')' => {
            Some((TokenKind::Rparen, 1))
        }
        b'*' => {
            Some((TokenKind::Multiply, 1))
        }
        b'+' => {
            if s.starts_with(b"+=") {
                return Some((TokenKind::AddAssign, 2));
            }
            Some((TokenKind::Plus, 1))
        }
        b',' => {
            Some((TokenKind::Comma, 1))
        }
        b'-' => {
            if s.starts_with(b"->") {
                return Some((TokenKind::Arrow, 2));
            }
            Some((TokenKind::Minus, 1))
        }
        b'.' => {
            if s.starts_with(b"...") {
                return Some((TokenKind::MultiplicityRange, 3));
            }
            if s.starts_with(b"..") {
                return Some((TokenKind::Dotdot, 2));
            }
            Some((TokenKind::Dot, 1))
        }
        b'/' => {
            Some((TokenKind::Divide, 1))
        }
        b':' => {
            if s.starts_with(b"::=") {
                return Some((TokenKind::Coloncolonequal, 3));
            }
            if s.starts_with(b"::") {
                return Some((TokenKind::Coloncolon, 2));
            }
            if s.starts_with(b":=") {
                return Some((TokenKind::ResetAssign, 2));
            }
            Some((TokenKind::Colon, 1))
        }
        b';' => {
            Some((TokenKind::Semicolon, 1))
        }
        b'<' => {
            if s.starts_with(b"<<") {
                return Some((TokenKind::StereotypeQualifierOpen, 2));
            }
            if s.starts_with(b"<=") {
                return Some((TokenKind::LessEqual, 2));
            }
            if s.starts_with(b"<>") {
                return Some((TokenKind::NotEqual, 2));
            }
            Some((TokenKind::Less, 1))
        }
        b'=' => {
            Some((TokenKind::Equal, 1))
        }
        b'>' => {
            if s.starts_with(b">=") {
                return Some((TokenKind::GreaterEqual, 2));
            }
            if s.starts_with(b">>") {
                return Some((TokenKind::StereotypeQualifierClose, 2));
            }
            Some((TokenKind::Greater, 1))
        }
        b'?' => {
            Some((TokenKind::Questionmark, 1))
        }
        b'@' => {
            Some((TokenKind::AtSign, 1))
        }
        b'[' => {
            Some((TokenKind::Lbracket, 1))
        }
        b']' => {
            Some((TokenKind::Rbracket, 1))
        }
        b'{' => {
            Some((TokenKind::Lbrace, 1))
        }
        b'|' => {
            Some((TokenKind::Bar, 1))
        }
        b'}' => {
            Some((TokenKind::Rbrace, 1))
        }
        b'~' => {
            Some((TokenKind::TildeSign, 1))
        }
        _ => None,
    }
}

