/// Binary operator levels from `EssentialOCL.gi` (with QVTo's additions), loosest first.
/// All are left-associative.
pub const BINARY_LEVELS: &[(&str, &[TokenKind])] = &[
    ("implies", &[TokenKind::KwImplies]),
    ("xor", &[TokenKind::KwXor]),
    ("or", &[TokenKind::KwOr]),
    ("and", &[TokenKind::KwAnd]),
    ("equality", &[TokenKind::Equal, TokenKind::NotEqual, TokenKind::NotEqualExeq]),
    ("relational", &[TokenKind::Greater, TokenKind::Less, TokenKind::GreaterEqual, TokenKind::LessEqual]),
    ("additive", &[TokenKind::Plus, TokenKind::Minus]),
    ("multiplicative", &[TokenKind::Multiply, TokenKind::Divide]),
];

/// The binding level of a binary operator: index into [`BINARY_LEVELS`] plus one.
#[inline]
pub const fn binary_level(k: TokenKind) -> u8 {
    match k {
        TokenKind::KwImplies => 1,
        TokenKind::KwXor => 2,
        TokenKind::KwOr => 3,
        TokenKind::KwAnd => 4,
        TokenKind::Equal | TokenKind::NotEqual | TokenKind::NotEqualExeq => 5,
        TokenKind::Greater | TokenKind::Less | TokenKind::GreaterEqual | TokenKind::LessEqual => 6,
        TokenKind::Plus | TokenKind::Minus => 7,
        TokenKind::Multiply | TokenKind::Divide => 8,
        _ => 0,
    }
}

